// And groups predicates with the AND operator between them.
func And(predicates ...predicate.WikiPage) predicate.WikiPage {
	return predicate.WikiPage(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.WikiPage) predicate.WikiPage {
	return predicate.WikiPage(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.WikiPage) predicate.WikiPage {
	return predicate.WikiPage(sql.NotPredicates(p))
}
